#!/usr/bin/env python3
"""Compute ground truth for CSX-235_Q1."""

from __future__ import annotations

import csv
import json
import re
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-235_Q1"
EVENT_ID = "CSX-235"
TARGET_FAMILY = "palu_geophysical_hazard_chain_score_ledger"
REPO_ROOT = Path(__file__).resolve().parents[3]
PACKAGE = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUT = Path(__file__).resolve().parent / "computed_gt.json"


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []
        self.skip_depth = 0

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag.lower() in {"script", "style", "noscript"}:
            self.skip_depth += 1

    def handle_endtag(self, tag: str) -> None:
        if tag.lower() in {"script", "style", "noscript"} and self.skip_depth:
            self.skip_depth -= 1

    def handle_data(self, data: str) -> None:
        if not self.skip_depth and data.strip():
            self.parts.append(data.strip())

    def text(self) -> str:
        return re.sub(r"\s+", " ", " ".join(self.parts)).strip()


def read_json(rel_path: str) -> Any:
    with (PACKAGE / rel_path).open("r", encoding="utf-8") as f:
        return json.load(f)


def clean_ascii(text: str) -> str:
    replacements = {
        "\u00a0": " ",
        "\u2018": "'",
        "\u2019": "'",
        "\u201c": '"',
        "\u201d": '"',
        "\u2013": "-",
        "\u2014": "-",
    }
    for old, new in replacements.items():
        text = text.replace(old, new)
    text = text.encode("ascii", errors="ignore").decode("ascii")
    return re.sub(r"\s+", " ", text).strip()


def html_text(raw: str) -> str:
    parser = TextExtractor()
    parser.feed(raw)
    return clean_ascii(parser.text())


def embedded_product_text(feature: dict[str, Any], product_name: str) -> str:
    parts: list[str] = []
    products = feature["properties"].get("products", {}).get(product_name, [])
    for product in products:
        for content in product.get("contents", {}).values():
            embedded = content.get("bytes")
            if embedded:
                parts.append(html_text(embedded))
    return clean_ascii(" ".join(parts))


def first_product_properties(feature: dict[str, Any], product_name: str) -> dict[str, Any]:
    products = feature["properties"].get("products", {}).get(product_name, [])
    return products[0].get("properties", {}) if products else {}


def count_files() -> tuple[int, dict[str, int]]:
    with (PACKAGE / "metadata" / "files.csv").open("r", encoding="utf-8-sig", newline="") as f:
        rows = list(csv.DictReader(f))
    counts: dict[str, int] = {}
    for row in rows:
        category = row["data_category"]
        counts[category] = counts.get(category, 0) + 1
    return len(rows), dict(sorted(counts.items()))


def osm_counts(rel_path: str) -> dict[str, int]:
    data = read_json(rel_path)
    counts = {
        "elements": 0,
        "roads": 0,
        "schools": 0,
        "hospitals": 0,
        "healthcare": 0,
        "bridges": 0,
    }
    for element in data.get("elements", []):
        counts["elements"] += 1
        tags = element.get("tags", {})
        if "highway" in tags:
            counts["roads"] += 1
        if tags.get("amenity") == "school":
            counts["schools"] += 1
        if tags.get("amenity") == "hospital":
            counts["hospitals"] += 1
        if "healthcare" in tags:
            counts["healthcare"] += 1
        if "bridge" in tags:
            counts["bridges"] += 1
    counts["facility_total"] = (
        counts["schools"] + counts["hospitals"] + counts["healthcare"] + counts["bridges"]
    )
    return counts


def parse_impact_values(text: str) -> dict[str, int | float]:
    patterns = {
        "reported_killed": r"At least ([0-9,]+) people killed",
        "reported_displaced": r"([0-9,]+) displaced",
        "wave_height_m": r"wave height of ([0-9.]+) m",
    }
    values: dict[str, int | float] = {}
    for key, pattern in patterns.items():
        match = re.search(pattern, text, flags=re.IGNORECASE)
        if not match:
            raise ValueError(f"missing impact value for {key}")
        raw = match.group(1).replace(",", "")
        values[key] = float(raw) if "." in raw else int(raw)
    return values


def capped(value: float, denominator: float) -> float:
    return min(value / denominator, 1.0)


def passfail(condition: bool) -> str:
    return "pass" if condition else "fail"


def build_result() -> dict[str, Any]:
    file_count, category_counts = count_files()
    event = read_json("metadata/event.json")
    feature = read_json("data/event_catalogs/event_catalogs_004_USGS_event_GeoJSON_us1000h3p4.json")
    worldpop = read_json("data/exposure_impact/exposure_impact_003_WorldPop_GP_100m_population_sum.json")
    alpha = read_json("data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json")
    gpm = read_json("data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json("data/physical_hazard/physical_hazard_005_CHIRPS_daily_event_accumulated_precipitation.json")

    properties = feature["properties"]
    ground_failure = first_product_properties(feature, "ground-failure")
    shakemap = first_product_properties(feature, "shakemap")
    impact_values = parse_impact_values(embedded_product_text(feature, "impact-text"))
    osm = osm_counts("data/exposure_impact/exposure_impact_004_OpenStreetMap_Overpass_bounded_AOI_slice.json")

    raw = {
        "magnitude": float(properties["mag"]),
        "mmi": round(float(properties["mmi"]), 3),
        "pga_g": round(float(shakemap["maxpga"]), 3),
        "liquefaction_alert_population": int(float(ground_failure["liquefaction-population-alert-value"])),
        "wave_height_m": float(impact_values["wave_height_m"]),
        "population": round(float(worldpop["population_sum"]["population"])),
        "facility_total": osm["facility_total"],
        "schools": osm["schools"],
        "hospitals": osm["hospitals"],
        "healthcare": osm["healthcare"],
        "bridges": osm["bridges"],
        "reported_killed": int(impact_values["reported_killed"]),
        "reported_displaced": int(impact_values["reported_displaced"]),
        "mean_embedding_change": round(float(alpha["stats"]["alphaearth_1_minus_cosine_mean"]), 4),
        "gpm_mean_mm": round(float(gpm["stats"]["gpm_event_precip_mm_mean"]), 2),
        "chirps_mean_mm": round(float(chirps["stats"]["chirps_event_precip_mm_mean"]), 2),
    }

    s_term = (
        capped(raw["magnitude"], 7.5)
        + capped(raw["mmi"], 8.0)
        + capped(raw["pga_g"], 0.8)
    ) / 3.0
    l_term = capped(raw["liquefaction_alert_population"], 140000.0)
    w_term = capped(raw["wave_height_m"], 7.0)
    p_term = capped(raw["population"], 500000.0)
    f_term = capped(raw["facility_total"], 40.0)
    h_term = min(
        ((raw["reported_killed"] / 2000.0) + (raw["reported_displaced"] / 200000.0)) / 2.0,
        1.0,
    )
    c_term = capped(raw["mean_embedding_change"], 0.10)
    r_term = capped((raw["gpm_mean_mm"] + raw["chirps_mean_mm"]) / 2.0, 25.0)

    components = {
        "S": round(s_term, 3),
        "L": round(l_term, 3),
        "W": round(w_term, 3),
        "P": round(p_term, 3),
        "F": round(f_term, 3),
        "H": round(h_term, 3),
        "C": round(c_term, 3),
        "R": round(r_term, 3),
    }
    positive_tests = {
        "S": s_term >= 0.95,
        "L": l_term >= 0.95,
        "W": w_term >= 0.95,
        "P": p_term >= 0.75,
        "F": f_term >= 0.75,
        "H": h_term >= 0.95,
        "C": c_term >= 0.50,
    }
    ledger = [
        {"term": term, "value": components[term], "threshold_result": passfail(test)}
        for term, test in positive_tests.items()
    ]
    rainfall_pass = r_term < 0.25
    ledger.append({"term": "R", "value": components["R"], "threshold_result": passfail(rainfall_pass)})

    positive_count = sum(positive_tests.values())
    score = round(
        100.0
        * (
            0.20 * s_term
            + 0.18 * l_term
            + 0.14 * w_term
            + 0.14 * p_term
            + 0.12 * f_term
            + 0.15 * h_term
            + 0.07 * c_term
            - 0.05 * r_term
        ),
        1,
    )
    final_label = (
        "coupled_geophysical_high_consistency"
        if score >= 85.0 and positive_count >= 6 and rainfall_pass
        else "not_high_consistency_by_this_score"
    )

    primary_gt = {
        "component_ledger": ledger,
        "score": score,
        "positive_terms_passing": positive_count,
        "final_label": final_label,
        "rejected_readings": [
            "rainfall_led",
            "image_only",
            "loss_total_only",
            "single_driver_score",
        ],
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": TARGET_FAMILY,
        "primary_gt": primary_gt,
        "event": {
            "package_id": EVENT_ID,
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "hazard_label": event["hazard_label"],
            "event_date_or_window": "2018-09-28",
            "location": "Palu, Central Sulawesi, Indonesia",
            "file_count": file_count,
            "category_counts": category_counts,
        },
        "decision_rule": {
            "summary": "Compute eight normalized terms and assign the high-consistency label only when the weighted score is at least 85, at least six positive terms pass, and the rainfall term stays below 0.25.",
            "score_formula": "100*(0.20S+0.18L+0.14W+0.14P+0.12F+0.15H+0.07C-0.05R)",
            "positive_thresholds": {"S": 0.95, "L": 0.95, "W": 0.95, "P": 0.75, "F": 0.75, "H": 0.95, "C": 0.50},
            "rainfall_threshold": {"R_lt": 0.25},
            "score_threshold": 85.0,
        },
        "key_values": {
            "raw_inputs": raw,
            "normalized_terms": components,
            "component_ledger": ledger,
            "score": score,
            "positive_terms_passing": positive_count,
            "rainfall_deduction_points": round(100.0 * 0.05 * r_term, 1),
            "final_label": final_label,
            "rejected_readings": [
                "rainfall_led",
                "image_only",
                "loss_total_only",
                "single_driver_score",
            ],
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "JSON ledger completeness",
                    "points": 3,
                    "description": "Returns eight named ledger rows plus score, positive-term count, final label, and rejected readings.",
                    "partial_credit": "Award 1-2 points for a mostly complete structure with missing rows or missing summary fields.",
                },
                {
                    "name": "Raw value extraction",
                    "points": 4,
                    "description": "Extracts M7.5, MMI 8.367, PGA 0.903 g, liquefaction alert population 140000, wave height 7 m, population 407654, facility total 37, killed 2077, displaced 206524, embedding mean 0.0531, and precipitation means 4.43 and 3.67 mm.",
                    "partial_credit": "Award 2-3 points for most values with minor rounding mistakes, and 1 point for only a few correct anchors.",
                },
                {
                    "name": "Normalized terms",
                    "points": 4,
                    "description": "Computes S=1.000, L=1.000, W=1.000, P=0.815, F=0.925, H=1.000, C=0.531, and R=0.162 within tolerance.",
                    "partial_credit": "Award 2-3 points for mostly correct terms with one or two formula errors.",
                },
                {
                    "name": "Weighted score",
                    "points": 4,
                    "description": "Applies the stated coefficients and reports 92.4 points out of 100 within 0.1.",
                    "partial_credit": "Award 2-3 points for the right formula with arithmetic or rounding errors.",
                },
                {
                    "name": "Threshold logic",
                    "points": 2,
                    "description": "Marks all seven positive terms as passing, marks the rainfall term as low, and assigns coupled_geophysical_high_consistency.",
                    "partial_credit": "Award 1 point if the final label is right but one threshold result is missing or wrong.",
                },
                {
                    "name": "Rejected readings",
                    "points": 2,
                    "description": "Rejects rainfall-led, image-only, loss-total-only, and single-driver readings using computed terms.",
                    "partial_credit": "Award 1 point for rejecting at least two readings with numeric support.",
                },
                {
                    "name": "Concise numeric framing",
                    "points": 1,
                    "description": "Keeps every statement tied to the weighted score or component ledger.",
                    "partial_credit": "Award 0.5 point for minor extra prose that does not change the result.",
                },
            ],
        },
        "question_conversion_audit": {
            "visible_list_framing_absent": True,
            "lettered_answer_absent": True,
            "calculation_first_design": True,
            "prescriptive_guidance_points": 0,
            "prose_centered_points": 0,
            "conversion_note_created": False,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "notes": "Computed from local CSX-235 records only.",
            "source_files": [
                "metadata/event.json",
                "metadata/files.csv",
                "data/event_catalogs/event_catalogs_004_USGS_event_GeoJSON_us1000h3p4.json",
                "data/exposure_impact/exposure_impact_003_WorldPop_GP_100m_population_sum.json",
                "data/exposure_impact/exposure_impact_004_OpenStreetMap_Overpass_bounded_AOI_slice.json",
                "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json",
                "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
                "data/physical_hazard/physical_hazard_005_CHIRPS_daily_event_accumulated_precipitation.json",
            ],
        },
    }


def main() -> None:
    OUT.write_text(json.dumps(build_result(), ensure_ascii=True, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
